{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE spf_b2c_final AS WITH main AS ( SELECT s.*, c.ORDER_ID, COALESCE(c.invoice_value, 0) AS cp_invoice_value, CASE WHEN c.pickup_pincode = \'560064\' THEN \'South\' WHEN c.pickup_pincode = \'122105\' THEN \'North\' ELSE \'Unknown\' END AS forward_location, CASE WHEN LOWER(s.AWB) LIKE \'%prz%\' THEN \'Prozo\' WHEN s.AWB LIKE \'2222%\' THEN \'Delhivery\' WHEN LOWER(s.AWB) LIKE \'%sni%\' THEN \'Ekart\' ELSE \'Other\' END AS courier, TO_CHAR( COALESCE( TRY_TO_DATE(s.date, \'DD-MM-YYYY\'), TRY_TO_DATE(s.date, \'DD/MM/YYYY\'), TRY_TO_DATE(s.date, \'DD Mon YYYY\'), TRY_TO_DATE(s.date, \'DD Month YYYY\'), TRY_TO_DATE(s.date, \'DD Mon\'), TRY_TO_DATE(s.date, \'DD Month\') ), \'YYYY-MM-DD\' ) AS date_formatted, CASE WHEN s.status ILIKE \'%Claim Denied%\' THEN \'Rejected\' WHEN LOWER(s.status) = \'rejected\' THEN \'Rejected\' WHEN LOWER(s.status) = \'dispute not accepted\' THEN \'Rejected\' WHEN LOWER(s.status) IN ( \'dispute accepted\',\'claim accepted\',\'approved\', \'approved \',\' partial dispute accepted\' ) THEN \'Accepted\' WHEN s.status ILIKE \'%Dispute Accepted%\' THEN \'Accepted\' WHEN s.status ILIKE \'%Claim Accepted%\' THEN \'Accepted\' WHEN s.status ILIKE \'%Partial Dispute Accepted%\' THEN \'Accepted\' WHEN LOWER(s.status) IN ( \'pending\',\'re-raised case\',\'open\', \'under investigation\',\'pending from snitch team\' ) THEN \'Open\' WHEN s.status IS NULL OR TRIM(s.status) = \'\' THEN \'Open\' ELSE \'Open\' END AS final_status, CASE WHEN s.reason ILIKE \'%awb does not belong%\' OR s.reason ILIKE \'%no issue%\' OR s.reason ILIKE \'%original photo%\' OR s.reason ILIKE \'%tid not matching%\' OR s.reason ILIKE \'%snitch logo%\' OR s.reason IS NULL THEN \'Invalid claim\' WHEN s.reason ILIKE \'%non qc%\' OR s.reason ILIKE \'%catalog image%\' OR s.reason ILIKE \'%catalogue image%\' OR s.reason ILIKE \'%qc%\' OR s.reason ILIKE \'%no parameter%\' THEN \'Non qc\' WHEN s.reason ILIKE \'%negative%\' OR s.reason ILIKE \'%pod%\' OR s.reason ILIKE \'%tamper%\' OR s.reason ILIKE \'%empty shipment%\' THEN \'Pod\' WHEN s.reason ILIKE \'%video%\' OR s.reason ILIKE \'%footage%\' OR s.reason ILIKE \'%unboxing%\' OR s.reason ILIKE \'%not visible%\' THEN \'footage issue\' WHEN s.reason ILIKE \'%out tat%\' OR s.reason ILIKE \'tat exceeded%\' OR (s.reason ILIKE \'%delivered on%\' AND s.reason ILIKE \'%raised on%\') THEN \'out tat\' WHEN s.reason ILIKE \'%approved%\' THEN \'approved\' WHEN TRIM(LOWER(s.reason)) IN ( \'checking with courier\', \'claim denied earlier but re-opedned the case\', \'under investigation\' ) THEN \'open\' ELSE \'Invalid claim\' END AS final_reason, CASE WHEN LOWER(s.\"Issue Category\") LIKE \'%other%brand%\' THEN \'Fake\' WHEN LOWER(s.\"Issue Category\") LIKE \'%oth% brand%\' THEN \'Fake\' WHEN LOWER(s.\"Issue Category\") LIKE \'%fake%\' THEN \'Fake\' WHEN LOWER(s.\"Issue Category\") LIKE \'%wrong product%\' AND LOWER(s.\"Issue Category\") NOT LIKE \'%same brand%\' AND LOWER(s.\"Issue Category\") NOT LIKE \'%own brand%\' THEN \'Fake\' WHEN LOWER(s.\"Issue Category\") LIKE \'%same brand%\' THEN \'Wpr\' WHEN LOWER(s.\"Issue Category\") LIKE \'%own brand%\' THEN \'Wpr\' WHEN LOWER(s.\"Issue Category\") LIKE \'%damage%\' THEN \'damage\' WHEN LOWER(s.\"Issue Category\") LIKE \'%damaged%\' THEN \'damage\' WHEN LOWER(s.\"Issue Category\") LIKE \'%damage product%\' THEN \'damage\' WHEN LOWER(s.\"Issue Category\") = \'empty box received\' THEN \'damage\' WHEN LOWER(s.\"Issue Category\") LIKE \'%empty box%\' THEN \'short qty\' WHEN LOWER(s.\"Issue Category\") LIKE \'%missing%\' THEN \'short qty\' WHEN LOWER(s.\"Issue Category\") LIKE \'%short%\' THEN \'short qty\' WHEN LOWER(s.\"Issue Category\") LIKE \'%partial%\' THEN \'short qty\' WHEN TRIM(s.\"Issue Category\") IN (\'\', \'0\') THEN \'other\' WHEN REGEXP_LIKE(s.\"Issue Category\", \'^[0-9.E+]+$\') THEN \'other\' ELSE \'other\' END AS final_issue_category FROM spf_b2c s LEFT JOIN cp_1 c ON UPPER(TRIM(s.awb)) = UPPER(TRIM(c.awb_number)) ), dedup AS ( SELECT * FROM ( SELECT main.*, ROW_NUMBER() OVER ( PARTITION BY UPPER(TRIM(awb)) ORDER BY awb ) rn FROM main ) WHERE rn = 1 ) SELECT * EXCLUDE rn FROM dedup;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            